            var data=Json.object().put("segmentId",r.text(segment,"ID")).put("itemId",r.text(segment,"itemId")).put("action",action).put("unit",r.text(segment,"unit")).put("eligibilityStatus",result.status).put("evaluatorVersion","quality-eligibility-v1");data.set("conditions",result.conditions);data.set("allowedRanges",dto(result.allowed));if(result.unknowns.contains("CURRENT_ELIGIBILITY_POLICY_UNRESOLVED")){data.putNull("eligibleQuantity");data.putNull("unreservedEligibleQuantity");}else {data.put("eligibleQuantity",decimal(quantity(result.allowed)));data.put("unreservedEligibleQuantity",decimal(unreserved));}if(result.boundary==null)data.putNull("nextValidityBoundary");else data.put("nextValidityBoundary",result.boundary.toString());data.set("conditionResults",conditionResults(segment,result));data.set("expiresAt",r.one(I+"ManufacturingLots",r.text(segment,"lotId")).path("expiresAt"));details.add(data);if(result.status.equals("CONFLICT"))conflicts.add(r.text(segment,"ID")+":ELIGIBILITY_CONFLICT");
