            var source=r.one(I+"QuantitySegments",r.text(allocation,"segmentId"));if(source.path("itemId").equals(scope.path("itemId"))&&matches(source,scope,"placeId","lotId")&&(!scope.hasNonNull("customerId")||scope.path("customerId").equals(allocation.path("customerId")))&&allowed("getInventory",PhysicalAuthorization.segmentTargets(source,null)))shortage=shortage.add(r.decimal(allocation,"quantity"));
