        var lot=r.one(I+"ManufacturingLots",r.text(segment,"lotId"));if(!lot.hasNonNull("expiresAt")){unknown.add("LOT_EXPIRY_UNKNOWN");conditions.add(condition("LOT_VALIDITY","UNKNOWN"));allowed=List.of();}else{Instant expires=time(lot,"expiresAt");boundary=future(boundary,expires.plusNanos(1000));var c=condition("LOT_VALIDITY",r.asOf.isAfter(expires)?"DENIED":"ALLOWED");c.set("evidenceRefs",strings(List.of(r.text(segment,"lotId"))));conditions.add(c);if(r.asOf.isAfter(expires))allowed=List.of();}
        var bases=r.known(I+"DispositionBases");for(String category:List.of("QC","CUSTOMER","COMMERCIAL")){var ranges=new ArrayList<Span>();var evidence=new TreeSet<String>();for(JsonNode base:bases)if(base.hasNonNull("segmentId")&&base.path("category").asText().equals(category)&&base.path("action").asText().equals(action)&&(!base.hasNonNull("customerId")||base.path("customerId").asText().equals(customer))){var projected=project(r,base.path("segmentId").asText(),r.text(segment,"ID"),start(base),r.decimal(base,"quantity"));if(projected.isEmpty())continue;boundary=permissionBoundary(boundary,base);if(active(base)&&qualityEvidence(base)){ranges.addAll(projected);refs.add(r.text(base,"evidenceRef"));evidence.add(r.text(base,"evidenceRef"));}}if(ranges.isEmpty())unknown.add(category+"_AUTHORITY_UNCONFIRMED");var c=condition(category,ranges.isEmpty()?"UNKNOWN":"ALLOWED");c.set("allowedRanges",dto(ranges));c.set("evidenceRefs",strings(evidence));conditions.add(c);allowed=intersect(allowed,ranges);}
        var regulatory=regulatory(segment,action);regulatory.conditions.forEach(conditions::add);unknown.addAll(regulatory.unknowns);refs.addAll(regulatory.refs);boundary=min(boundary,regulatory.boundary);allowed=intersect(allowed,regulatory.allowed);
        var blocks=new ArrayList<Span>();var blockRefs=new TreeSet<String>();var categoryRanges=new TreeMap<String,List<Span>>();var categoryRefs=new TreeMap<String,Set<String>>();
        for(JsonNode hold:r.known(I+"Restrictions"))if(hold.path("controlScope").equals(segment.path("controlScope"))&&Set.of(action,"ALL").contains(hold.path("action").asText())){
            var mapped=hold.hasNonNull("segmentId")?project(r,r.text(hold,"segmentId"),r.text(segment,"ID"),start(hold),r.decimal(hold,"quantity")):initial;if(mapped.isEmpty())continue;boundary=permissionBoundary(boundary,hold);if(!active(hold))continue;blocks.addAll(mapped);String category=hold.path("category").asText("UNCLASSIFIED");categoryRanges.computeIfAbsent(category,k->new ArrayList<>()).addAll(mapped);if(hold.hasNonNull("evidenceRef")){String ref=r.text(hold,"evidenceRef");refs.add(ref);blockRefs.add(ref);categoryRefs.computeIfAbsent(category,k->new TreeSet<>()).add(ref);}
        }
