            var procedure=r.one(R+"Procedures",r.text(d,"procedureId"));var local=versions.stream().filter(v->v.path("procedureId").equals(procedure.path("ID"))).toList();var heads=local.stream().filter(v->local.stream().noneMatch(n->n.path("previousVersionId").equals(v.path("ID")))).toList();if(heads.size()!=1||!heads.getFirst().path("ID").equals(d.path("procedureVersionId")))continue;JsonNode version=heads.getFirst();if(!version.path("status").asText().equals("SUBMITTED")||!PhysicalSourceProofs.verified(r,r.text(version,"occurrenceId"),actor))continue;
            var projected=intersect(project(r,r.text(d,"physicalScopeId"),r.text(segment,"ID"),start(d),r.decimal(d,"quantity")),List.of(new Span(BigDecimal.ZERO,r.decimal(segment,"quantity"))));if(projected.isEmpty())continue;boolean decision=d.path("decision").asText().equals("ALLOWED");regulatoryRefs.add(r.text(d,"occurrenceId"));(decision?rawAllowed:rawDenied).addAll(projected);var label=labelChecks.get(r.text(procedure,"ID"));if(!requiresLabel||label!=null&&label.status.equals("ALLOWED")){refs.add(r.text(d,"occurrenceId"));(decision?allowed:denied).addAll(projected);}
